import React from "react"
import Layout from "../components/layout"
import { graphql } from "gatsby"
import ServiceArea from "../components/construct/ServiceArea"
import SliderContent from "../components/construct/Slider"
import Seo from "../components/seo"
import Hire from "../components/construct/Hire"
import Quote from "../components/construct/Quote"
import Partners from "../components/construct/Partners"

export const Head = () => (
  <Seo title="Servicios eléctricos integrales" />
)

const IndexPage = ({ data }) => {
  return (
    <Layout index={true}>
      <SliderContent />
      <ServiceArea data={data.servicios.nodes} />

      {/* <RecetProject /> */}
      <Hire />
      <Quote data={data.contacto.nodes} />
      {/* <LatestBlog /> */}
      <Partners />
    </Layout>
  )
}

export const query = graphql`
  query {
    servicios: allServiciosJson(
      filter: { href: { nin: "/servicios/medicion-pat/" } }
    ) {
      nodes {
        title
        description
        href
        image {
          childImageSharp {
            gatsbyImageData(
              placeholder: BLURRED
              formats: [AUTO, WEBP, AVIF]
              width: 370
              height: 188
            )
          }
        }
      }
    }
    contacto: allPagesJson(filter: { idPage: { eq: "contacto" } }) {
      nodes {
        idPage
        block1 {
          category
          title
        }
        block2 {
          category
          title
        }
      }
    }
    allPagesJson(filter: { idPage: { eq: "index" } }) {
      nodes {
        idPage
        content {
          category
          description
          title
        }
      }
    }
  }
`

export default IndexPage
