import { Link } from "gatsby"
import React from "react"
import { FaIcon } from "../FaIcon"
import { faEnvelope } from "@fortawesome/free-regular-svg-icons"

export default function SliderContent() {
  return (
    <section className="construct-slider-area">
      <div className="item construct-main-slide slide-item-1">
        <div className="construct-main-caption">
          <div className="construct-caption-cell">
            <div className="container">
              <div className="row">
                <div className="col-md-7 mr-auto">
                  <h2>
                    Seguridad Eléctrica Certificada para tu <span>Tranquilidad</span>
                  </h2>
                  <p>Servicios rápidos y confiables para la seguridad eléctrica de tus proyectos en CABA y GBA.</p>
                  <Link to="/servicios" className="construct-btn">
                    ver servicios
                  </Link>
                  <Link to="/contacto" className="construct-btn">
                    <FaIcon
                      icon={faEnvelope}
                      fill={"#fff"}
                      height={23}
                      width={23}
                      style={{ paddingRight: '5px' }}
                    />
                    contactanos
                  </Link>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}
